var isSupportMem64 = () => {
  try {
    // Constructor options can be accepted while actual memory64 modules fail to compile.
    return WebAssembly.validate(new Uint8Array([0, 97, 115, 109, 1, 0, 0, 0, 5, 3, 1, 4, 1]));
  } catch (e) {
    return false;
  }
};
